import concurrent.futures,hashlib,json,time
from pathlib import Path
import prepare_scripts as p
R=Path(__file__).parent;S=R/'voice/scripts'
source="""In a modern laboratory, a tiny sample can preserve information that the size and shape of the whole object cannot confidently reveal. Ancient DNA and proteins surviving in mammoth teeth provide different ways to determine whether a mammoth was female or male, depending on preservation. A study published in 2025 investigated material from39mammoths and confidently determined the biological sex of30mammoths. Among these tested mammoths,17were female mammoths and13were male mammoths. The researchers considered this consistent with access to mammoth herds rather than only solitary male mammoths. These numerical results describe the mammoth sample tested. They do not identify a particular group of human hunters, prove a hunting technique, or reveal the personal lives of the people who arranged the structure. Additional molecular analysis found different mammoth maternal lineages, making a simple picture of the whole collection coming from one family group dying together more complicated. Put two ideas together: people selected large animal remains, and the collection includes several different animal histories. Laboratory analysis adds biological relationships and distinctions, while excavation provides positions and archaeological associations. Each approach is more informative when checked against the other. A bone on a screen may look like an answer, but its real value may be a better question. To investigate human activity, that question leads from the largest objects towards traces small enough to float on water."""
source=source.replace('from39','from 39 ').replace('of30','of 30 ').replace(',17were',', 17 were').replace('and13were','and 13 were')
def run(loc):
    f=S/f'{loc}.json';a=json.loads(f.read_text());text=p.adapt(p.translate(source,p.LANGS[loc]),loc)
    a[5].update(voice=text,source_en=source,editorial_status='Mammoth-only biological sex terminology and numeric-sample meaning explicitly repaired;assistant review;independent native review pending')
    f.write_text(json.dumps(a,ensure_ascii=False,indent=2));f.with_suffix('.txt').write_text('\n\n'.join(x['voice'] for x in a));print('ANIMAL_SEX_CONTEXT_REPAIRED',loc,flush=True)
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:list(pool.map(run,[l for l in p.LANGS if l!='vi-VN']))
